export const TRUTHY_STRINGS: string[];
export const FALSEY_STRINGS: string[];

export type HandlerResult = {
  value?: unknown;
  next?: boolean;
};

export type ArgType = string | number | boolean | string[];
export type ArgTypeName = 'boolean' | 'integer' | 'string' | 'list';

export function isArgTypeName(name: string): name is ArgTypeName;

export const next: unique symbol;

type ArgsArg = Record<string, ArgType>;

type Handler = (
  value: ArgType | undefined,
  name: string,
  args: ArgsArg
) => HandlerResult | Symbol;

type Validator = (
  value: ArgType,
  name: string,
  args: ArgsArg
) => string | null | Symbol;

export interface OptionsDef {
  arg?: string[] | 'positional' | '--';
  default?: ArgType;
  description?: string;
  env?: string;
  handler?: Handler | Handler[];
  name: string;
  required?: boolean;
  silent?: boolean;
  type?: ArgTypeName;
  validator?: Validator | Validator[];
}

export interface ParserOptions {
  argv: string[];
  env: Record<string, string>;
  falsey: string[];
  truthy: string[];
}

export function argTypeName(name: string): ArgTypeName;

export const stringArg: ArgTypeName;
export const booleanArg: ArgTypeName;
export const integerArg: ArgTypeName;
export const listArg: ArgTypeName;

export class Parser {
  constructor(
    parserOptions: Partial<ParserOptions>,
    ...optionsDef: (OptionsDef[] | OptionsDef)[]
  );

  get args(): Record<string, unknown>;

  get rawNormalizedValues(): Record<string, ArgType> | null;

  get errors(): Record<string, string> | null;

  addOption(option: OptionsDef, reparseIfNecessary?: boolean): void;

  addOptions(...optionDefSet: (OptionsDef | OptionsDef[])[]): void;

  hasError(optionName: string): boolean;

  hasErrors(): boolean;

  parse(): boolean;

  reparseIfNecessary(): void;
}

export function parse(
  parserOptions: Partial<ParserOptions>,
  ...optionsDef: (OptionsDef[] | OptionsDef)[]
): Record<string, unknown>;

export default Parser;